// Package generator converts parsed Go declarations into TypeScript source code.
//
// This is the second stage of the gots pipeline:
//
//	Go source files → [parser] → ParseResult → [generator] → TypeScript files
//
// The generator takes a ParseResult (types, constants, structs) and a Config
// (styles, overrides, type maps) and produces .ts files.
//
// # Generation pipeline for a single source
//
// For each source entry in the config:
//
//  1. Write the header comment ("// Code generated by gots. DO NOT EDIT.")
//  2. Generate typed constants (enum-like patterns):
//     - Find all TypeDefs from this source file
//     - For each type, find its associated constants
//     - Apply include/exclude filters
//     - Resolve the output style (per-type override → source style → global default)
//     - Write the appropriate TypeScript format (union, enum, or const-object)
//  3. Generate untyped constants (standalone exports)
//  4. Generate structs (TypeScript interfaces)
//
// # Style resolution cascade
//
// The style for a type is resolved with most-specific-wins:
//
//	per-type override (config.overrides.MessageRole.style)
//	    → source-level default (config.sources[].style)
//	        → global default (config.default_style)
//
// # Prefix stripping
//
// Go convention is to prefix const names with the type name:
//
//	type MessageRole string
//	const MessageRoleUser MessageRole = "user"    // prefix "MessageRole"
//
// The generator strips this prefix to produce clean TypeScript keys:
//
//	MessageRoleUser → "User" (stripped "MessageRole" prefix)
//
// Safety: only strips if the remainder starts with an uppercase letter.
// "SomeOther" with prefix "S" → "omeOther" starts lowercase → don't strip.
package generator

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/khanakia/gots/pkg/config"
	"github.com/khanakia/gots/pkg/parser"
)

// Generator produces TypeScript output from parsed Go declarations.
//
// It holds references to the config (for style decisions, type maps, overrides)
// and the parse result (the actual Go declarations to convert).
type Generator struct {
	cfg    *config.Config       // Generation settings and overrides
	result *parser.ParseResult  // Parsed Go types, constants, structs
}

// New creates a new Generator with the given config and parse result.
func New(cfg *config.Config, result *parser.ParseResult) *Generator {
	return &Generator{
		cfg:    cfg,
		result: result,
	}
}

// GenerateString generates TypeScript output for a single source and returns it as a string.
// Used by the "convert" command to write to stdout instead of a file.
func (g *Generator) GenerateString(source config.Source) (string, error) {
	grouped := g.groupConstsByType()
	return g.generateSource(source, grouped)
}

// Generate runs the full generation pipeline.
//
// For each source in the config:
//  1. Generate TypeScript code for types/consts/structs from that source file
//  2. Write the output to the configured .ts file path
//
// Returns the first error encountered, if any.
func (g *Generator) Generate() error {
	// Pre-compute: group all constants by their Go type name.
	// This lets us quickly find "all constants of type MessageRole".
	// Untyped constants are grouped under the empty string key "".
	grouped := g.groupConstsByType()

	for _, source := range g.cfg.Sources {
		output, err := g.generateSource(source, grouped)
		if err != nil {
			return fmt.Errorf("generating %s: %w", source.File, err)
		}

		if err := g.writeFile(source.Output, output); err != nil {
			return fmt.Errorf("writing %s: %w", source.Output, err)
		}
	}

	return nil
}

// groupConstsByType creates a map from Go type name → list of constants.
//
// Example result:
//
//	{
//	    "MessageRole": [MessageRoleUser, MessageRoleAssistant, MessageRoleSystem],
//	    "FeedbackCategory": [FeedbackCategoryUIBug, ...],
//	    "": [DefaultAIModelID, HeaderWorkspaceId, ...],   // untyped consts
//	}
//
// The empty string key "" holds all untyped constants.
func (g *Generator) groupConstsByType() map[string][]parser.ConstDef {
	grouped := make(map[string][]parser.ConstDef)
	for _, c := range g.result.Consts {
		grouped[c.TypeName] = append(grouped[c.TypeName], c)
	}
	return grouped
}

// generateSource produces the full TypeScript output for a single source file.
//
// The output is built in three phases:
//  1. Typed constants — types with associated const values (enum-like patterns)
//  2. Untyped constants — standalone const exports
//  3. Structs — TypeScript interfaces
//
// Each declaration is filtered through shouldInclude() which checks the
// source's include/exclude patterns.
func (g *Generator) generateSource(source config.Source, grouped map[string][]parser.ConstDef) (string, error) {
	var sb strings.Builder

	// Write the header comment at the top of the file
	sb.WriteString(g.cfg.Header)
	sb.WriteString("\n\n")

	// Resolve the default style for this source.
	// Source-level style overrides the global default.
	style := source.Style
	if style == "" {
		style = g.cfg.DefaultStyle
	}

	// --- Phase 1: Typed constants (enum-like patterns) ---
	//
	// For each type declaration in this file, check if it has associated constants.
	// If so, generate the appropriate TypeScript output (union, enum, or const-object).
	//
	// Example: type MessageRole string + const MessageRoleUser MessageRole = "user"
	// → export type MessageRole = "user" | "assistant" | "system";
	for _, td := range g.result.Types {
		// Only process types from this source file
		if td.File != source.File {
			continue
		}
		// Apply include/exclude filters
		if !g.shouldInclude(td.Name, source) {
			continue
		}

		// Find all constants of this type
		consts, ok := grouped[td.Name]
		if !ok || len(consts) == 0 {
			// No constants — emit as a standalone type alias
			// e.g., type UserID int64 → export type UserID = number;
			g.writeTypeAlias(&sb, td)
			sb.WriteString("\n")
			continue
		}

		// Resolve style: per-type override → source style → global default
		typeStyle := style
		if ov, ok := g.cfg.Overrides[td.Name]; ok && ov.Style != "" {
			typeStyle = ov.Style
		}

		// Resolve name: per-type rename or keep the Go type name
		tsName := td.Name
		if ov, ok := g.cfg.Overrides[td.Name]; ok && ov.Name != "" {
			tsName = ov.Name
		}

		// Determine if this is a numeric type (int, uint, etc.)
		// to decide whether values should be quoted or not.
		isNumeric := isNumericGoType(td.Underlying)

		// Emit doc comment if present
		writeComment(&sb, td.Comment, "")

		// Generate the TypeScript output in the resolved style
		switch typeStyle {
		case "union":
			g.writeUnion(&sb, tsName, consts, isNumeric)
		case "enum":
			g.writeEnum(&sb, tsName, td.Name, consts, isNumeric)
		case "const-object":
			g.writeConstObject(&sb, tsName, td.Name, consts, isNumeric)
		default:
			g.writeUnion(&sb, tsName, consts, isNumeric)
		}

		// Optionally emit a companion values array.
		// Per-type override takes precedence over global setting.
		emitValues := g.cfg.EmitValuesArray
		if ov, ok := g.cfg.Overrides[td.Name]; ok {
			emitValues = ov.ValuesArray
		}
		if emitValues {
			g.writeValuesArray(&sb, tsName, consts, isNumeric)
		}

		sb.WriteString("\n")
	}

	// --- Phase 2: Untyped constants ---
	//
	// Constants without an explicit Go type (e.g., const Foo = "bar").
	// These are exported as individual const declarations.
	untypedConsts := grouped[""]
	for _, c := range untypedConsts {
		if c.File != source.File {
			continue
		}
		if !g.shouldInclude(c.Name, source) {
			continue
		}
		g.writeStandaloneConst(&sb, c)
	}

	// --- Phase 3: Structs ---
	//
	// Each struct becomes a TypeScript interface.
	// Fields are mapped using the type map and struct tag config.
	for _, sd := range g.result.Structs {
		if sd.File != source.File {
			continue
		}
		if !g.shouldInclude(sd.Name, source) {
			continue
		}
		g.writeStruct(&sb, sd)
		sb.WriteString("\n")
	}

	return sb.String(), nil
}

// --- TypeScript output writers ---
//
// Each writer handles one output style. They all take:
//   - sb:         string builder to append output to
//   - tsName:     the TypeScript name (may differ from Go name if renamed)
//   - goTypeName: the original Go type name (used for prefix stripping)
//   - consts:     the list of constants belonging to this type

// writeUnion generates a TypeScript union type.
//
// Output:
//
//	export type MessageRole = "user" | "assistant" | "system";
func (g *Generator) writeUnion(sb *strings.Builder, tsName string, consts []parser.ConstDef, isNumeric bool) {
	values := make([]string, 0, len(consts))
	for _, c := range consts {
		if isNumeric {
			values = append(values, c.Value)
		} else {
			values = append(values, fmt.Sprintf(`"%s"`, c.Value))
		}
	}
	fmt.Fprintf(sb, "export type %s = %s;\n", tsName, strings.Join(values, " | "))
}

// writeEnum generates a TypeScript enum.
//
// Output:
//
//	export enum MessageRole {
//	  User = "user",
//	  Assistant = "assistant",
//	  System = "system",
//	}
//
// The Go type name prefix is stripped from constant names to produce clean keys:
// MessageRoleUser → User
func (g *Generator) writeEnum(sb *strings.Builder, tsName, goTypeName string, consts []parser.ConstDef, isNumeric bool) {
	fmt.Fprintf(sb, "export enum %s {\n", tsName)
	for _, c := range consts {
		key := stripPrefix(c.Name, goTypeName)
		if isNumeric {
			fmt.Fprintf(sb, "  %s = %s,\n", key, c.Value)
		} else {
			fmt.Fprintf(sb, "  %s = \"%s\",\n", key, c.Value)
		}
	}
	sb.WriteString("}\n")
}

// writeConstObject generates a const object + type alias pattern.
//
// Output:
//
//	export const MessageRole = {
//	  User: "user",
//	  Assistant: "assistant",
//	  System: "system",
//	} as const;
//	export type MessageRole = typeof MessageRole[keyof typeof MessageRole];
//
// This pattern provides both runtime values (for lookups, iteration) and
// compile-time types (for type checking). Best of both worlds.
func (g *Generator) writeConstObject(sb *strings.Builder, tsName, goTypeName string, consts []parser.ConstDef, isNumeric bool) {
	fmt.Fprintf(sb, "export const %s = {\n", tsName)
	for _, c := range consts {
		key := stripPrefix(c.Name, goTypeName)
		if isNumeric {
			fmt.Fprintf(sb, "  %s: %s,\n", key, c.Value)
		} else {
			fmt.Fprintf(sb, "  %s: \"%s\",\n", key, c.Value)
		}
	}
	sb.WriteString("} as const;\n")
	// The type alias extracts the union of all values from the const object.
	fmt.Fprintf(sb, "export type %s = typeof %s[keyof typeof %s];\n", tsName, tsName, tsName)
}

// writeValuesArray generates a companion array of all values.
//
// Output:
//
//	export const MessageRoleValues = ["user", "assistant", "system"] as const;
//
// Useful for dropdowns, validation, and iteration.
func (g *Generator) writeValuesArray(sb *strings.Builder, tsName string, consts []parser.ConstDef, isNumeric bool) {
	values := make([]string, 0, len(consts))
	for _, c := range consts {
		if isNumeric {
			values = append(values, c.Value)
		} else {
			values = append(values, fmt.Sprintf(`"%s"`, c.Value))
		}
	}
	fmt.Fprintf(sb, "export const %sValues = [%s] as const;\n", tsName, strings.Join(values, ", "))
}

// writeStandaloneConst generates a single exported constant.
//
// For single-line values:
//
//	export const DefaultAIModelID = "openai_gpt_4";
//
// For multi-line values (Go backtick strings → TS template literals):
//
//	export const DefaultAIInstruction = `You are a helpful assistant.
//	You are knowledgeable...`;
func (g *Generator) writeStandaloneConst(sb *strings.Builder, c parser.ConstDef) {
	writeComment(sb, c.Comment, "")
	if c.IsMultiLine {
		// Multi-line Go backtick strings → TypeScript template literals (backticks)
		fmt.Fprintf(sb, "export const %s = `%s`;\n", c.Name, c.Value)
	} else if isNumericValue(c.Value) {
		// Numeric values: no quotes (768 not "768")
		fmt.Fprintf(sb, "export const %s = %s;\n", c.Name, c.Value)
	} else if c.Value == "true" || c.Value == "false" {
		// Boolean values: no quotes (true not "true")
		fmt.Fprintf(sb, "export const %s = %s;\n", c.Name, c.Value)
	} else {
		// String values: double quotes
		fmt.Fprintf(sb, "export const %s = \"%s\";\n", c.Name, c.Value)
	}
}

// writeTypeAlias generates a TypeScript type alias for a Go named type
// that has no associated constants.
//
// Output:
//
//	export type UserID = number;
//	export type Slug = string;
//	export type Tags = string[];
func (g *Generator) writeTypeAlias(sb *strings.Builder, td parser.TypeDef) {
	writeComment(sb, td.Comment, "")
	typeParamsStr := g.formatTypeParams(td.TypeParams)

	// Function types with parsed signatures → full TypeScript function type
	if td.FuncSig != nil {
		tsFunc := g.funcSigToTS(td.FuncSig)
		fmt.Fprintf(sb, "export type %s%s = %s;\n", td.Name, typeParamsStr, tsFunc)
		return
	}
	// Use fullGoTypeToTS to handle composite underlying types:
	// []string → string[], map[string]int → Record<string, number>, etc.
	tsType := g.fullGoTypeToTS(td.Underlying)
	fmt.Fprintf(sb, "export type %s%s = %s;\n", td.Name, typeParamsStr, tsType)
}

// writeStruct generates a TypeScript interface from a Go struct.
//
// Output:
//
//	export interface User {
//	  id: number;
//	  name: string;
//	  email?: string;
//	}
//
// Field names come from struct tags (configurable — json by default).
// Types are mapped through the type map (config.type_map) and built-in rules.
// Pointer fields become optional (?) based on pointer_handling config.
// Unexported fields and embedded structs are skipped.
func (g *Generator) writeStruct(sb *strings.Builder, sd parser.StructDef) {
	// Emit struct-level doc comment
	writeComment(sb, sd.Comment, "")

	// Collect embedded struct names for the extends clause.
	// type BlogPost struct { Timestamps; SoftDelete; Title string }
	// → export interface BlogPost extends Timestamps, SoftDelete { title: string; }
	var embeds []string
	for _, f := range sd.Fields {
		if f.IsEmbedded && f.IsExported {
			embeds = append(embeds, f.GoType)
		}
	}

	// Build the interface declaration with optional generic type parameters and extends.
	typeParamsStr := g.formatTypeParams(sd.TypeParams)
	extendsStr := ""
	if len(embeds) > 0 {
		extendsStr = " extends " + strings.Join(embeds, ", ")
	}
	fmt.Fprintf(sb, "export interface %s%s%s {\n", sd.Name, typeParamsStr, extendsStr)

	for _, f := range sd.Fields {
		// Skip unexported fields (lowercase in Go)
		if !f.IsExported {
			continue
		}
		// Embedded structs are handled via extends clause above — skip here
		if f.IsEmbedded {
			continue
		}

		// Check if the field should be skipped via json:"-" tag
		if g.shouldSkipField(f) {
			continue
		}

		// Emit field-level comment
		writeComment(sb, f.Comment, "  ")

		// Resolve field name from struct tag (e.g., json:"created_at" → created_at)
		fieldName := g.resolveFieldName(f)

		// Handle pointer fields based on config
		optional := ""
		if f.IsPointer && g.cfg.PointerHandling == "optional" {
			optional = "?"
		}

		// Handle inline anonymous struct fields — emit nested object type
		if f.IsInlineStruct && len(f.InlineFields) > 0 {
			fmt.Fprintf(sb, "  %s%s: {\n", fieldName, optional)
			g.writeInlineFields(sb, f.InlineFields, "    ")
			sb.WriteString("  };\n")
			continue
		}

		// Handle function-type fields with parsed signatures
		if f.FuncSig != nil {
			tsFunc := g.funcSigToTS(f.FuncSig)
			fmt.Fprintf(sb, "  %s%s: %s;\n", fieldName, optional, tsFunc)
			continue
		}

		// Convert the full Go type expression to TypeScript recursively.
		// This handles nested composites: [][]int, map[string][]int, etc.
		tsType := g.fullGoTypeToTS(f.FullType)

		fmt.Fprintf(sb, "  %s%s: %s;\n", fieldName, optional, tsType)
	}
	sb.WriteString("}\n")
}

// writeInlineFields emits fields for an anonymous inline struct with custom indentation.
// Supports recursive nesting (inline struct inside inline struct).
func (g *Generator) writeInlineFields(sb *strings.Builder, fields []parser.StructField, indent string) {
	for _, f := range fields {
		if !f.IsExported {
			continue
		}
		if f.IsEmbedded {
			continue
		}
		if g.shouldSkipField(f) {
			continue
		}

		fieldName := g.resolveFieldName(f)
		optional := ""
		if f.IsPointer && g.cfg.PointerHandling == "optional" {
			optional = "?"
		}

		// Recursive: inline struct inside inline struct
		if f.IsInlineStruct && len(f.InlineFields) > 0 {
			fmt.Fprintf(sb, "%s%s%s: {\n", indent, fieldName, optional)
			g.writeInlineFields(sb, f.InlineFields, indent+"  ")
			fmt.Fprintf(sb, "%s};\n", indent)
			continue
		}

		tsType := g.fullGoTypeToTS(f.FullType)
		fmt.Fprintf(sb, "%s%s%s: %s;\n", indent, fieldName, optional, tsType)
	}
}

// --- Function type rendering ---

// funcSigToTS converts a parsed Go function signature to a TypeScript function type.
//
// Conversion rules:
//   - context.Context params are stripped (no TS equivalent)
//   - error returns are stripped (TS uses exceptions)
//   - Multiple non-error returns → tuple [T1, T2]
//   - Single non-error return → T
//   - No returns (or only error) → void
//   - Unnamed params get generated names: arg0, arg1, ...
//
// Examples:
//
//	func(a, b int) int                      → (a: number, b: number) => number
//	func(err error)                         → (err: Error) => void
//	func()                                  → () => void
//	func(request string) (string, error)    → (request: string) => string
//	func(next Handler) Handler              → (next: Handler) => Handler
//	func(a, b int) (int, int, error)        → (a: number, b: number) => [number, number]
//	func(ctx context.Context, req Request) (Response, error) → (req: Request) => Response
func (g *Generator) funcSigToTS(sig *parser.FuncSig) string {
	// Build parameter list, skipping context.Context
	params := make([]string, 0, len(sig.Params))
	argIdx := 0
	for _, p := range sig.Params {
		// Skip context.Context — no TS equivalent
		if p.Type == "context.Context" {
			continue
		}

		tsType := g.fullGoTypeToTS(p.Type)
		name := p.Name
		if name == "" {
			name = fmt.Sprintf("arg%d", argIdx)
		}
		params = append(params, name+": "+tsType)
		argIdx++
	}

	// Build return type, stripping error
	var nonErrorResults []string
	for _, r := range sig.Results {
		if r.Type == "error" {
			continue
		}
		nonErrorResults = append(nonErrorResults, g.fullGoTypeToTS(r.Type))
	}

	var returnType string
	switch len(nonErrorResults) {
	case 0:
		returnType = "void"
	case 1:
		returnType = nonErrorResults[0]
	default:
		// Multiple returns → TypeScript tuple
		returnType = "[" + strings.Join(nonErrorResults, ", ") + "]"
	}

	return fmt.Sprintf("(%s) => %s", strings.Join(params, ", "), returnType)
}

// --- Type mapping ---

// fullGoTypeToTS recursively converts a full Go type expression string to TypeScript.
//
// Handles nested composites that flat flags can't represent:
//
//	"string"                      → "string"
//	"*string"                     → "string"
//	"[]int"                       → "number[]"
//	"[][]int"                     → "number[][]"
//	"[]*User"                     → "User[]"
//	"map[string]int"              → "Record<string, number>"
//	"map[string][]int"            → "Record<string, number[]>"
//	"map[string]map[string]string" → "Record<string, Record<string, string>>"
//	"[]map[string]int"            → "Record<string, number>[]"
//	"*[]string"                   → "string[]"
func (g *Generator) fullGoTypeToTS(fullType string) string {
	// Handle pointer: strip leading * and recurse
	if strings.HasPrefix(fullType, "*") {
		return g.fullGoTypeToTS(fullType[1:])
	}

	// Handle slice/array: strip leading [] and append [] at the end
	if strings.HasPrefix(fullType, "[]") {
		inner := g.fullGoTypeToTS(fullType[2:])
		return inner + "[]"
	}

	// Handle map: map[K]V → Record<tsK, tsV>
	if strings.HasPrefix(fullType, "map[") {
		keyType, valType := splitMapType(fullType)
		tsKey := g.fullGoTypeToTS(keyType)
		tsVal := g.fullGoTypeToTS(valType)
		return fmt.Sprintf("Record<%s, %s>", tsKey, tsVal)
	}

	// Base case: simple type name — use the existing type mapper
	return g.goTypeToTS(fullType)
}

// splitMapType splits "map[K]V" into key and value type strings.
// Handles nested maps: "map[string]map[string]string" → ("string", "map[string]string")
func splitMapType(s string) (key, value string) {
	// Skip "map["
	if !strings.HasPrefix(s, "map[") {
		return "string", "unknown"
	}
	s = s[4:] // skip "map["

	// Find the matching ] for the key — handle nested brackets
	depth := 1
	i := 0
	for i < len(s) && depth > 0 {
		if s[i] == '[' {
			depth++
		} else if s[i] == ']' {
			depth--
		}
		if depth > 0 {
			i++
		}
	}

	if depth != 0 {
		return "string", "unknown"
	}

	key = s[:i]
	value = s[i+1:] // skip the closing ]

	return key, value
}

// goTypeToTS converts a Go type name to its TypeScript equivalent.
//
// Resolution order:
//  1. Custom type map from config (e.g., time.Time → string)
//  2. Built-in primitive mapping (string → string, int → number, etc.)
//  3. Passthrough — use the Go type name as-is (assumes it's a known TS type)
func (g *Generator) goTypeToTS(goType string) string {
	// 1. Check custom type map first — user config takes priority
	if ts, ok := g.cfg.TypeMap[goType]; ok {
		return ts
	}

	// 2. Built-in Go → TypeScript primitive mapping
	switch goType {
	case "string":
		return "string"
	case "bool":
		return "boolean"
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64", "byte", "rune", "uintptr":
		return "number"
	case "complex64", "complex128":
		// Complex numbers have no JSON equivalent — map to unknown
		return "unknown"
	case "interface{}", "any":
		return g.cfg.EmptyInterface // "unknown" or "any" based on config
	case "map":
		// Bare "map" from unresolved map types — fallback to Record
		return "Record<string, unknown>"
	case "struct":
		// Anonymous empty struct (e.g., chan struct{}) — void/undefined signal
		return "void"
	case "Function":
		// Function type used as a field — generic callable
		return "Function"
	case "error":
		// Go's error interface → TypeScript Error class
		return "Error"
	case "interface":
		// Named interface type — placeholder until full interface generation
		return "unknown"
	case "unknown":
		return "unknown"
	default:
		// 3. Passthrough — could be a struct name (User), or an unmapped
		// package type (custom.Type). The generated TS will reference it by name.
		return goType
	}
}

// --- Field name resolution ---

// resolveFieldName determines the TypeScript field name for a struct field.
//
// It reads the configured struct tag (default: "json") to find the serialized name.
// Example: `json:"created_at,omitempty"` → "created_at"
//
// Falls back to the Go field name if:
//   - No struct tag exists
//   - The tag value is "-" (field is hidden from serialization)
//   - The tag key doesn't exist in the tag string
func (g *Generator) resolveFieldName(f parser.StructField) string {
	tag := f.Tag
	if tag == "" {
		return f.Name // No tag → use Go field name
	}

	// Look up the configured tag key (e.g., "json")
	tagKey := g.cfg.StructTag
	tagValue := lookupTag(tag, tagKey)
	if tagValue == "" || tagValue == "-" {
		return f.Name
	}

	// Strip options after comma: "name,omitempty" → "name"
	if idx := strings.Index(tagValue, ","); idx != -1 {
		tagValue = tagValue[:idx]
	}

	if tagValue == "" {
		return f.Name
	}

	return tagValue
}

// formatTypeParams converts parsed Go type parameters to a TypeScript generic string.
//
// Examples:
//
//	[]                           → ""
//	[{T, any}]                   → "<T>"
//	[{K, comparable}, {V, any}]  → "<K extends string | number, V>"
//	[{T, int | int64 | float64}] → "<T extends number>"
//
// Go constraints are mapped to TypeScript:
//   - "any"        → no constraint (just T)
//   - "comparable" → "extends string | number" (TS approximation)
//   - "int | int64 | float64" → "extends number" (all numeric → number)
//   - "string"     → "extends string"
func (g *Generator) formatTypeParams(params []parser.TypeParam) string {
	if len(params) == 0 {
		return ""
	}

	parts := make([]string, 0, len(params))
	for _, p := range params {
		tsConstraint := g.goConstraintToTS(p.Constraint)
		if tsConstraint == "" {
			parts = append(parts, p.Name)
		} else {
			parts = append(parts, p.Name+" extends "+tsConstraint)
		}
	}
	return "<" + strings.Join(parts, ", ") + ">"
}

// goConstraintToTS maps a Go type constraint to a TypeScript extends clause.
//
// Returns empty string for unconstrained params (any), meaning no "extends" needed.
func (g *Generator) goConstraintToTS(constraint string) string {
	switch constraint {
	case "any":
		// Unconstrained — no extends needed
		return ""
	case "comparable":
		// comparable ≈ types that support == in Go
		// In TS, approximate with string | number
		return "string | number"
	case "string":
		return "string"
	case "bool":
		return "boolean"
	default:
		// Check if all parts of a union constraint are numeric
		if isAllNumericConstraint(constraint) {
			return "number"
		}
		// Check if all parts are string types
		if isAllStringConstraint(constraint) {
			return "string"
		}
		// Mixed or complex — pass through as-is or drop constraint
		return ""
	}
}

// isAllNumericConstraint checks if a union constraint like "int | int64 | float64"
// consists entirely of Go numeric types, meaning it maps to "number" in TS.
func isAllNumericConstraint(constraint string) bool {
	parts := strings.Split(constraint, "|")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		part = strings.TrimPrefix(part, "~")
		if !isNumericGoType(part) {
			return false
		}
	}
	return len(parts) > 0
}

// isAllStringConstraint checks if a union constraint consists entirely of string types.
func isAllStringConstraint(constraint string) bool {
	parts := strings.Split(constraint, "|")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		part = strings.TrimPrefix(part, "~")
		if part != "string" {
			return false
		}
	}
	return len(parts) > 0
}

// shouldSkipField returns true if a struct field should be excluded from output.
//
// A field is skipped when:
//   - Its struct tag value is "-" for the configured tag key (e.g., json:"-")
//   - This means the field is explicitly hidden from serialization
func (g *Generator) shouldSkipField(f parser.StructField) bool {
	// Function fields with json:"-" should still be emitted — they're callbacks,
	// not data fields. json:"-" only means "not serialized", but in TS interfaces
	// function properties are valid and useful.
	if f.FuncSig != nil {
		return false
	}
	if f.Tag == "" {
		return false
	}
	tagValue := lookupTag(f.Tag, g.cfg.StructTag)
	return tagValue == "-"
}

// --- Include/exclude filtering ---

// shouldInclude checks whether a type or constant name passes the
// source's include/exclude filters.
//
// Logic:
//  1. If include list is non-empty, name must match at least one pattern
//  2. If name matches any exclude pattern, it's excluded
//  3. If no include list, everything is included (minus excludes)
//
// Patterns support * wildcard at start or end: "Message*", "*Status"
func (g *Generator) shouldInclude(name string, source config.Source) bool {
	// Whitelist check: if include patterns are specified, name must match one
	if len(source.Include) > 0 {
		matched := false
		for _, pattern := range source.Include {
			if matchPattern(pattern, name) {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}

	// Blacklist check: if name matches any exclude pattern, skip it
	for _, pattern := range source.Exclude {
		if matchPattern(pattern, name) {
			return false
		}
	}

	return true
}

// --- File I/O ---

// writeFile writes the generated TypeScript content to disk.
// Creates parent directories if they don't exist.
func (g *Generator) writeFile(path string, content string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("creating directory %s: %w", dir, err)
	}
	return os.WriteFile(path, []byte(content), 0644)
}

// --- Helper functions ---

// stripPrefix removes the Go type name prefix from a constant name
// to produce a clean TypeScript key.
//
// Examples:
//
//	stripPrefix("MessageRoleUser", "MessageRole")     → "User"
//	stripPrefix("MessageRoleAssistant", "MessageRole") → "Assistant"
//	stripPrefix("Active", "Status")                    → "Active" (no prefix match)
//	stripPrefix("SomeOther", "S")                      → "SomeOther" (remainder starts lowercase)
//
// Safety guard: the remainder must start with an uppercase letter.
// This prevents false matches like stripping "S" from "SomeOther" → "omeOther".
func stripPrefix(constName, typeName string) string {
	if strings.HasPrefix(constName, typeName) {
		rest := constName[len(typeName):]
		// Only strip if remainder starts with uppercase — prevents partial prefix matches
		if len(rest) > 0 && rest[0] >= 'A' && rest[0] <= 'Z' {
			return rest
		}
	}
	return constName
}

// matchPattern performs simple glob matching with a single * wildcard.
//
// Supported patterns:
//   - Exact match:   "MessageRole" matches "MessageRole"
//   - Prefix match:  "Message*"    matches "MessageRole", "MessageType"
//   - Suffix match:  "*Status"     matches "OrderStatus", "UserStatus"
//
// Does NOT support mid-string wildcards like "Msg*Role" — use exact names for those.
func matchPattern(pattern, name string) bool {
	if pattern == name {
		return true
	}
	if strings.HasSuffix(pattern, "*") {
		return strings.HasPrefix(name, pattern[:len(pattern)-1])
	}
	if strings.HasPrefix(pattern, "*") {
		return strings.HasSuffix(name, pattern[1:])
	}
	return false
}

// lookupTag extracts a tag value from a Go struct tag string.
//
// Go struct tags look like: `json:"name,omitempty" yaml:"name"`
// This function finds the value for a specific key.
//
// Example:
//
//	lookupTag(`json:"created_at,omitempty" yaml:"created_at"`, "json")
//	→ "created_at,omitempty"
//
// The caller is responsible for further parsing (stripping ",omitempty" etc).
//
// Implementation: manually parses the tag string rather than using reflect.StructTag
// because we're working with raw strings from the AST, not reflect values.
func lookupTag(tag, key string) string {
	// Remove surrounding backticks: `json:"foo"` → json:"foo"
	tag = strings.Trim(tag, "`")

	for tag != "" {
		// Skip leading whitespace between tag pairs
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			break
		}

		// Read the tag key (everything before ':')
		i = 0
		for i < len(tag) && tag[i] != ':' && tag[i] != '"' && tag[i] != ' ' {
			i++
		}
		if i >= len(tag) {
			break
		}

		tagKey := tag[:i]
		tag = tag[i:]

		// Expect :"value" after the key
		if len(tag) < 2 || tag[0] != ':' || tag[1] != '"' {
			break
		}
		tag = tag[2:] // Skip :"

		// Read until closing quote
		i = 0
		for i < len(tag) && tag[i] != '"' {
			i++
		}
		if i >= len(tag) {
			break
		}

		tagValue := tag[:i]
		tag = tag[i+1:] // Skip closing "

		// Return if this is the key we're looking for
		if tagKey == key {
			return tagValue
		}
	}

	return ""
}

// writeComment emits a JSDoc-style comment block if the comment is non-empty.
//
// Single-line:  /** comment */
// Multi-line:
//
//	/**
//	 * line 1
//	 * line 2
//	 */
func writeComment(sb *strings.Builder, comment, indent string) {
	if comment == "" {
		return
	}
	lines := strings.Split(comment, "\n")
	if len(lines) == 1 {
		fmt.Fprintf(sb, "%s/** %s */\n", indent, lines[0])
	} else {
		fmt.Fprintf(sb, "%s/**\n", indent)
		for _, line := range lines {
			if line == "" {
				fmt.Fprintf(sb, "%s *\n", indent)
			} else {
				fmt.Fprintf(sb, "%s * %s\n", indent, line)
			}
		}
		fmt.Fprintf(sb, "%s */\n", indent)
	}
}

// isNumericGoType returns true if the Go underlying type is numeric.
// Used to decide whether constant values should be quoted in TS output.
func isNumericGoType(underlying string) bool {
	switch underlying {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64", "byte", "rune", "uintptr":
		return true
	default:
		return false
	}
}

// isNumericValue checks if a string looks like a number (int or float).
// Used to decide whether a constant value should be quoted in TS output.
func isNumericValue(s string) bool {
	if s == "" {
		return false
	}
	for i, c := range s {
		if c >= '0' && c <= '9' {
			continue
		}
		if c == '.' && i > 0 {
			continue
		}
		if c == '-' && i == 0 {
			continue
		}
		return false
	}
	return true
}
